  1 | import { useCallback, useRef, useState, useEffect } from "react";
  2 | import { usePlayerWithAudio } from "./hooks/usePlayerWithAudio";
  3 | import { useMetadata } from "./hooks/useMetadata";
  4 | import { useTauri } from "./hooks/useTauri";
  5 | import { useAudioVisualizer } from "./hooks/useAudioVisualizer";
  6 | import { useFavorites } from "./hooks/useFavorites";
  7 | import { useHistory } from "./hooks/useHistory";
  8 | import {
  9 |   TitleBar,
 10 |   Playlist,
 11 |   PlayerControls,
 12 |   ProgressBar,
 13 |   StatusBar,
 14 |   DriveBrowser,
 15 |   AudioVisualizer,
 16 |   HistoryPanel,
 17 | } from "./components";
 18 | import type { Track } from "./types";
 19 | 
 20 | const FAVORITES_STORAGE_KEY = "llama-player-favorites";
 21 | 
 22 | function App() {
 23 |   const {
 24 |     state,
 25 |     play,
 26 |     pause,
 27 |     next,
 28 |     prev,
 29 |     seek,
 30 |     setVolume,
 31 |     addTrack,
 32 |     toggleShuffle,
 33 |     reorderPlaylist,
 34 |     toggleFavorite,
 35 |     loadFavorites: loadPlayerFavorites,
 36 |     audioRef,
 37 |   } = usePlayerWithAudio([]);
 38 | 
 39 |   const { processFiles } = useMetadata();
 40 |   const {
 41 |     state: tauriState,
 42 |     openFilePicker,
 43 |     filePathToUrl,
 44 |     sendNotification,
 45 |     registerShortcuts,
 46 |   } = useTauri();
 47 | 
 48 |   const { loadFavorites } = useFavorites();
 49 |   const history = useHistory();
 50 | 
 51 |   const [isLoading, setIsLoading] = useState(false);
 52 |   const [showDrive, setShowDrive] = useState(false);
 53 |   const [showHistory, setShowHistory] = useState(false);
 54 |   const [isCompact, setIsCompact] = useState(false);
 55 | 
 56 |   const fileInputRef = useRef<HTMLInputElement>(null);
 57 | 
 58 |   // Carrega favoritos salvos ao iniciar
 59 |   useEffect(() => {
 60 |     const savedFavorites = loadFavorites();
 61 |     if (savedFavorites.length > 0) {
 62 |       loadPlayerFavorites(savedFavorites);
 63 |     }
 64 |     // eslint-disable-next-line react-hooks/exhaustive-deps
 65 |   }, []);
 66 | 
 67 |   // Registra atalhos de teclado (Media Session API + Tauri global shortcuts)
 68 |   useEffect(() => {
 69 |     const cleanup = registerShortcuts({
 70 |       MediaPlayPause: () => (state.isPlaying ? pause() : play()),
 71 |       MediaNextTrack: () => next(),
 72 |       MediaPrevTrack: () => prev(),
 73 |       MediaStop: () => pause(),
 74 |     });
 75 | 
 76 |     return () => {
 77 |       cleanup.then((fn) => fn());
 78 |     };
 79 |   }, [registerShortcuts, state.isPlaying, pause, play, next, prev]);
 80 | 
 81 |   // Media Session API (navegador)
 82 |   useEffect(() => {
 83 |     if (!("mediaSession" in navigator)) return;
 84 | 
 85 |     navigator.mediaSession.metadata = new MediaMetadata({
 86 |       title: state.currentTrack?.title ?? "Llama Player",
 87 |       artist: state.currentTrack?.artist ?? undefined,
 88 |       album: state.currentTrack?.album ?? undefined,
 89 |     });
 90 | 
 91 |     navigator.mediaSession.setActionHandler("play", () => play());
 92 |     navigator.mediaSession.setActionHandler("pause", () => pause());
 93 |     navigator.mediaSession.setActionHandler("nexttrack", () => next());
 94 |     navigator.mediaSession.setActionHandler("previoustrack", () => prev());
 95 |   }, [state.currentTrack, play, pause, next, prev]);
 96 | 
 97 |   // Notificação ao trocar de música + histórico
 98 |   useEffect(() => {
 99 |     if (state.currentTrack && state.isPlaying) {
100 |       sendNotification(
101 |         `▶ ${state.currentTrack.title}`,
102 |         state.currentTrack.artist
103 |           ? `Por ${state.currentTrack.artist}`
104 |           : undefined
105 |       );
106 |       history.addEntry(state.currentTrack);
107 |     }
108 |   }, [state.currentTrack?.id, state.isPlaying]); // eslint-disable-line react-hooks/exhaustive-deps
109 | 
110 |   const visualizer = useAudioVisualizer(audioRef, state.isPlaying);
111 | 
112 |   const handleSelectTrack = (track: Track) => {
113 |     play(track);
114 |   };
115 | 
116 |   const handleOpenFile = async () => {
117 |     if (tauriState.isTauri) {
118 |       // Usa file picker nativo do Tauri
119 |       setIsLoading(true);
120 |       try {
121 |         const paths = await openFilePicker();
122 |         if (!paths || paths.length === 0) return;
123 | 
124 |         // Converte paths para File objects (via fetch do asset protocol)
125 |         const tracks: Track[] = [];
126 |         for (const path of paths) {
127 |           const url = await filePathToUrl(path);
128 |           const name = path.split(/[/\\]/).pop() || path;
129 |           tracks.push({
130 |             id: `local-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
131 |             title: name.replace(/\.[^/.]+$/, ""),
132 |             duration: 0,
133 |             src: url,
134 |           });
135 |         }
136 | 
137 |         for (const track of tracks) {
138 |           addTrack(track);
139 |         }
140 | 
141 |         if (!state.currentTrack && tracks.length > 0) {
142 |           play(tracks[0]);
143 |         }
144 |       } catch (err) {
145 |         console.error("[Llama Player] Erro ao abrir arquivos:", err);
146 |       } finally {
147 |         setIsLoading(false);
148 |       }
149 |     } else {
150 |       // Fallback: input file HTML
151 |       fileInputRef.current?.click();
152 |     }
153 |   };
154 | 
155 |   const handleFileChange = useCallback(
156 |     async (e: React.ChangeEvent<HTMLInputElement>) => {
157 |       const files = e.target.files;
158 |       if (!files || files.length === 0) return;
159 | 
160 |       setIsLoading(true);
161 | 
162 |       try {
163 |         const fileArray = Array.from(files);
164 |         const tracks = await processFiles(fileArray);
165 | 
166 |         for (const track of tracks) {
167 |           addTrack(track);
168 |         }
169 | 
170 |         // If nothing is playing, start with the first track
171 |         if (!state.currentTrack && tracks.length > 0) {
172 |           play(tracks[0]);
173 |         }
174 |       } catch (err) {
175 |         console.error("[Llama Player] Erro ao processar arquivos:", err);
176 |       } finally {
177 |         setIsLoading(false);
178 |       }
179 | 
180 |       // Reset input so the same file can be selected again
181 |       e.target.value = "";
182 |     },
183 |     [processFiles, addTrack, state.currentTrack, play]
184 |   );
185 | 
186 |   const handleDropFiles = useCallback(
187 |     async (files: FileList) => {
188 |       setIsLoading(true);
189 |       try {
190 |         const fileArray = Array.from(files);
191 |         const tracks = await processFiles(fileArray);
192 |         for (const track of tracks) {
193 |           addTrack(track);
194 |         }
195 |         if (!state.currentTrack && tracks.length > 0) {
196 |           play(tracks[0]);
197 |         }
198 |       } catch (err) {
199 |         console.error("[Llama Player] Erro ao processar arquivos arrastados:", err);
200 |       } finally {
201 |         setIsLoading(false);
202 |       }
203 |     },
204 |     [processFiles, addTrack, state.currentTrack, play]
205 |   );
206 | 
207 |   const handleAddDriveTracks = useCallback(
208 |     (tracks: Track[]) => {
209 |       for (const track of tracks) {
210 |         addTrack(track);
211 |       }
212 |       if (!state.currentTrack && tracks.length > 0) {
213 |         play(tracks[0]);
214 |       }
215 |     },
216 |     [addTrack, state.currentTrack, play]
217 |   );
218 | 
219 |   return (
220 |     <div className="app">
221 |       <TitleBar />
222 | 
223 |       <main className="main-content">
224 |         <div className="toolbar">
225 |           <button
226 |             className="toolbar-btn"
227 |             onClick={handleOpenFile}
228 |             disabled={isLoading}
229 |             title="Abrir arquivo de áudio local"
230 |           >
231 |             {isLoading ? "⏳ Lendo metadados..." : "📂 Arquivo local"}
232 |           </button>
233 |           <input
234 |             ref={fileInputRef}
235 |             type="file"
236 |             accept="audio/*"
237 |             multiple
238 |             style={{ display: "none" }}
239 |             onChange={handleFileChange}
240 |           />
241 |           <button
242 |             className={`toolbar-btn ${showDrive ? "toolbar-btn-active" : ""}`}
243 |             onClick={() => setShowDrive((v) => !v)}
244 |             title="Google Drive"
245 |           >
246 |             ☁️ Drive
247 |           </button>
248 |           <button
249 |             className={`toolbar-btn ${showHistory ? "toolbar-btn-active" : ""}`}
250 |             onClick={() => setShowHistory((v) => !v)}
251 |             title="Histórico de reprodução"
252 |           >
253 |             🕐 Histórico
254 |           </button>
255 |         </div>
256 | 
257 |         {showDrive && (
258 |           <DriveBrowser onAddTracks={handleAddDriveTracks} />
259 |         )}
260 | 
261 |         {showHistory && (
262 |           <HistoryPanel
263 |             entries={history.entries}
264 |             onSelectTrack={handleSelectTrack}
265 |             onClear={history.clear}
266 |           />
267 |         )}
268 | 
269 |         <Playlist
270 |           tracks={state.playlist}
271 |           currentTrackId={state.currentTrack?.id ?? null}
272 |           isPlaying={state.isPlaying}
273 |           onSelectTrack={handleSelectTrack}
274 |           onReorderPlaylist={reorderPlaylist}
275 |           onDropFiles={handleDropFiles}
276 |           onToggleFavorite={toggleFavorite}
277 |         />
278 | 
279 |         <PlayerControls
280 |           currentTrack={state.currentTrack}
281 |           currentTrackId={state.currentTrack?.id ?? null}
282 |           isPlaying={state.isPlaying}
283 |           isShuffled={state.isShuffled}
284 |           isCompact={isCompact}
285 |           onPlay={() => play()}
286 |           onPause={pause}
287 |           onNext={next}
288 |           onPrev={prev}
289 |           onToggleShuffle={toggleShuffle}
290 |           onToggleFavorite={toggleFavorite}
291 |           onToggleCompact={() => setIsCompact((v) => !v)}
292 |         />
293 | 
294 |         <AudioVisualizer
295 |           frequencyData={visualizer.frequencyData}
296 |           waveformData={visualizer.waveformData}
297 |           isActive={visualizer.isActive}
298 |         />
299 | 
300 |         <ProgressBar
301 |           currentTime={state.currentTime}
302 |           duration={state.duration}
303 |           onSeek={seek}
304 |         />
305 |       </main>
306 | 
307 |       <StatusBar
308 |         isPlaying={state.isPlaying}
309 |         volume={state.volume}
310 |         onVolumeChange={setVolume}
311 |       />
312 |     </div>
313 |   );
314 | }
315 | 
316 | export default App;
